document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll('[class*="wp-block-"]');if(!e.length)return;const t=window.innerHeight,o=Array.from(e).filter(e=>!e.closest("footer, .site-footer, #colophon")&&e.getBoundingClientRect().top>=t);if(!o.length)return;o.forEach(e=>e.classList.add("reveal-on-scroll"));const r=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),t.unobserve(e.target))})},{root:null,rootMargin:"0px 0px -50px 0px",threshold:.15});o.forEach(e=>r.observe(e))});